#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp=[&](int x,int y){
        // x>=1, y>=1, x+y<n (i.e., x+y<=n-1)
        ops.push_back({x,y});
        vector<int> res;
        for(int i=n-y;i<n;i++) res.push_back(p[i]);
        for(int i=x;i<n-y;i++) res.push_back(p[i]);
        for(int i=0;i<x;i++) res.push_back(p[i]);
        p=res;
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==placed+1){ pos=i; break; }
        if(pos==placed) continue;

        int remaining = n - placed; // elements not yet placed (indices placed..n-1)
        // pos >= placed since elements 1..placed are already at 0..placed-1

        // Work within the subarray [placed..n-1]. We need to move element from pos to placed.
        // Strategy: use operations to achieve this.

        // Step 1: Move element to position n-1
        if(pos != n-1){
            // op: x = pos+1, y = n-1-pos
            // x+y = pos+1+n-1-pos = n. Need x+y <= n-1. Too big.
            // Instead: x = pos-placed+1 (but we need placed elements undisturbed)
            // Actually we need x >= placed+1 to not disturb placed elements... no.
            // We need prefix = p[0..placed-1] to stay... but the operation moves prefix to end.
            // So we must ensure x > placed (take all placed elements plus some, then they end up at the end... no good)

            // Simpler: if pos < n-1, do op x=pos+1, y=1 => suffix=[p[n-1]], mid=[p[pos+1]..p[n-2]], prefix=[p[0..pos]]
            // Result: p[n-1], p[pos+1..n-2], p[0..pos]. Target p[pos] goes to position n-1.
            // Need x+y=pos+2<=n-1 => pos<=n-3. If pos==n-2, x=n-1,y=1,x+y=n. Too big.
            if(pos <= n-3){
                doOp(pos+1, 1);
            } else { // pos == n-2
                doOp(1, 2); // brings p[n-2..n-1] to front, p[0] to end
                // now find again
                for(int i=0;i<n;i++) if(p[i]==placed+1){ pos=i; break; }
                if(pos!=n-1 && pos<=n-3) doOp(pos+1,1);
                else if(pos==n-1) {} // done
                else { doOp(1,1); for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;} if(pos!=n-1&&pos<=n-3) doOp(pos+1,1); }
            }
            for(int i=0;i<n;i++) if(p[i]==placed+1){ pos=i; break; }
        }
        // Step 2: Move from n-1 to placed
        if(pos==n-1 && placed<n-1){
            // x=placed, y=1 => [p[n-1], p[placed..n-2], p[0..placed-1]]. Target at 0 = placed? No, at 0.
            // Then need to fix prefix. Use x=1, y=placed => [p[n-placed..n-1], p[1..n-placed-1], p[0]]
            doOp(placed+1, 1); // [p[n-1], p[placed+1..n-2], p[0..placed]]. placed+1 elems at end include target's destination
            // Hmm let me just simulate carefully
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos!=placed){
                doOp(1, n-1-placed);
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
